    final class V260MeasurementTailFulfillment {
        private Database $db;public function __construct(Database $db){$this->db=$db;}
        public function execute(string $route,array $actor,array $body):array {if($route!=='orders.measurement.rework')throw new \RuntimeException('unexpected fulfillment route '.$route);$order=$this->db->fetch('SELECT * FROM orders WHERE BINARY public_no=BINARY :no FOR UPDATE',['no'=>(string)$body['order_id']]);if(!$order||(int)$order['user_id']!==(int)($actor['user_id']??0))throw new OrderOperationException('只能操作自己的测量单','FORBIDDEN',403);$state=$this->db->fetch('SELECT * FROM order_measurement_states WHERE order_id=:id FOR UPDATE',['id'=>(int)$order['id']]);if(!$state||(string)$state['result_status']!=='submitted'||(string)$order['fulfillment_status']!=='submitted'||(string)$order['lifecycle_status']!=='active')throw new OrderOperationException('当前状态不能补测','MEASUREMENT_REWORK_NOT_ALLOWED',409);$count=(int)$this->db->fetchValue("SELECT COUNT(*) FROM order_events WHERE order_id=:id AND event_type='measurement_rework_requested'",['id'=>(int)$order['id']]);if($count>=1)throw new OrderOperationException('普通测量仅支持一次补测','MEASUREMENT_REWORK_LIMIT',409);$this->db->execute("UPDATE order_measurement_states SET result_status='editing',submitted_at=NULL,auto_accept_at=NULL,updated_at=UTC_TIMESTAMP() WHERE order_id=:id",['id'=>(int)$order['id']]);$this->db->execute("UPDATE orders SET fulfillment_status='in_progress',completion_submitted_at=NULL,version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=:id",['id'=>(int)$order['id']]);$this->db->insert("INSERT INTO order_events(order_id,event_type,actor_type,actor_id,payload_json,created_at) VALUES(:order,'measurement_rework_requested','user',:actor,:payload,UTC_TIMESTAMP())",['order'=>(int)$order['id'],'actor'=>(int)$actor['user_id'],'payload'=>json_encode(['reason'=>(string)$body['reason']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return['message'=>'已退回补测','data'=>['rework_count'=>1]];}
    }
}
